export default function archiveDates({timestamp}) {
  const current=new Date(timestamp);
  if(!Number.isFinite(current.getTime()))throw new Error('Invalid schedule timestamp.');
  const month=current.getUTCMonth(),day=current.getUTCDate(),dates=[];
  for(let year=current.getUTCFullYear();year>=2007;year--){
    const date=new Date(Date.UTC(year,month,day));
    if(date.getUTCMonth()!==month||date.getUTCDate()!==day)continue;
    const value=date.toISOString().slice(0,10);
    if(value<'2007-02-19')continue;
    dates.push(value);
  }
  return {dates,count:dates.length};
}

