import{setTimeout as delay}from'node:timers/promises';

export async function collectArchives({dates},context,wait) {
  const pages=[];
  for(let index=0;index<dates.length;index++){
    context.signal?.throwIfAborted();
    if(index)await wait(3000,undefined,{signal:context.signal});
    const url=new URL('https://news.ycombinator.com/front');
    url.searchParams.set('day',dates[index]);
    const timeout=AbortSignal.timeout(30000);
    const signal=context.signal?AbortSignal.any([context.signal,timeout]):timeout;
    const response=await context.fetch(url,{method:'GET',signal});
    if(!response.ok)throw new Error('Hacker News archive failed with HTTP '+response.status+'.');
    pages.push({date:dates[index],html:await response.text()});
  }
  return {pages};
}

export default function collectHackerNews(input,context) {
  return collectArchives(input,context,delay);
}

